CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_METER_READING_MONTH_REGION_SEGMENT
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_METER_READING at grain Date.FiscalYear, Date.MonthName, Date.Quarter, Customer.CustomerSegment, Location.Region, Date.MonthNumber; covers 26.81% of weighted demand (1 clusters); est. 240 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       c3.CUSTOMER_SEGMENT,
       l4.REGION,
       d1.MONTH_NUMBER,
       SUM(f.CO2_ESTIMATE_KG) AS CO2_ESTIMATE_KG,
       SUM(f.CONSUMPTION_KWH) AS CONSUMPTION_KWH,
       SUM(f.CONSUMPTION_MWH) AS CONSUMPTION_MWH,
       SUM(f.OFF_PEAK_KWH) AS OFF_PEAK_KWH,
       MAX(f.PEAK_DEMAND_KW) AS PEAK_DEMAND_KW,
       SUM(f.REACTIVE_KVARH) AS REACTIVE_KVARH,
       COUNT(*) AS METER_READING_COUNT
FROM CORE.FCT_METER_READING f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_METER m2 ON f.METER_ID = m2.METER_ID
JOIN CORE.DIM_CUSTOMER c3 ON m2.CUSTOMER_ID = c3.CUSTOMER_ID
JOIN CORE.DIM_LOCATION l4 ON m2.LOCATION_ID = l4.LOCATION_ID
GROUP BY ALL;

-- Dynamic tables refresh with the owner's privileges: re-apply source policies on the aggregate.
ALTER DYNAMIC TABLE AGG.AGG_METER_READING_MONTH_REGION_SEGMENT ADD ROW ACCESS POLICY SEC.RAP_REGION ON (REGION);
